sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	$scope.showName =function(name){
		console.log('this name is ' + name);
		console.log('this c is ' + c);//c->[object Object] 
		console.log(c.data.table.list) //list 数据可以获取
	}
};

sp_widget.script:
(function() {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
	data.userName = gs.getUserName().toString();

	data.table={
		'list':[]
	}
	var grUser = new GlideRecord("sys_user");
	grUser.addNotNullQuery("phone");
	grUser.setLimit(5);
	grUser.query();
	while(grUser.next()){
		var obj ={};
		obj.userID =grUser.getValue('user_name');
		obj.name =grUser.getValue('first_name');
		obj.email =grUser.getValue('email');
		data.table.list.push(obj);
	}
	gs.info("data-list:"+JSON.stringify(data.table.list,null,4))
})();
